INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 1, 'ما هي وحدة نقل البيانات (PDU) الخاصة بطبقة الشبكة (Network Layer) في نموذج الاتصال المعياري OSI؟', 'Bits (البتات)', 'Frames (الإطارات)', 'Packets (الحزم)', 'Segments (المقاطع)', 'C', 'وحدة PDU في طبقة الشبكة (Layer 3) تسمى Packet، بينما في طبقة ربط البيانات تسمى Frame، وفي طبقة النقل تسمى Segment، وفي الطبقة الفيزيائية تسمى Bits.', 'easy', 'OSI Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 2, 'أي من أجهزة الشبكة التالية يقوم بفصل مجالات التصادم (Collision Domains) مع إبقاء الأجهزة ضمن نفس مجال البث (Broadcast Domain) افتراضياً؟', 'الموزع القديم (Hub)', 'المبدل (Switch)', 'المكرر (Repeater)', 'جدار الحماية فقط', 'B', 'المبدل (Switch) يوفر مجال تصادم مستقل تماماً لكل منفذ من منافذه، لكنه افتراضياً يمرر حزم البث العام (Broadcasts) لجميع المنافذ إلا عند إنشاء شبكات VLAN افتراضية.', 'medium', 'Network Hardware');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 1, 'في أي طبقة من طبقات نموذج OSI يتم تنفيذ العنونة الفيزيائية المعتمدة على عنوان الـ MAC Address؟', 'الطبقة الفيزيائية (Physical Layer)', 'طبقة ربط البيانات (Data Link Layer)', 'طبقة الشبكة (Network Layer)', 'طبقة النقل (Transport Layer)', 'B', 'عناوين MAC هي عناوين فيزيائية تعمل في الطبقة الثانية (Data Link Layer)، وتحديداً في الطبقة الفرعية MAC Sublayer (IEEE 802.3).', 'easy', 'OSI Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 4, 'ما البروتوكول المسؤول عن توفير نقل موثوق للبيانات عبر المصافحة الثلاثية (Three-Way Handshake) والتحكم بالتدفق؟', 'UDP', 'TCP', 'IP', 'ICMP', 'B', 'بروتوكول TCP هو بروتوكول موثوق (Connection-Oriented) في طبقة النقل يستخدم المصافحة الثلاثية (SYN, SYN-ACK, ACK) ويضمن تسليم البيانات وإعادة إرسال المفقود منها.', 'easy', 'Transport Protocols');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 1, 'ما الترتيب الصحيح لعملية تغليف البيانات (Encapsulation) عند انتقالها من التطبيق نزولاً نحو الوسط الناقل؟', 'Data -> Packet -> Frame -> Segment -> Bits', 'Data -> Segment -> Packet -> Frame -> Bits', 'Data -> Frame -> Packet -> Segment -> Bits', 'Segment -> Packet -> Data -> Frame -> Bits', 'B', 'تبدأ البيانات كـ Data في طبقات التطبيقات، ثم تقسم إلى Segments في طبقة النقل، ثم تغلف كـ Packets بإضافة IP Header، ثم Frames بإضافة MAC Header، وأخيراً تتحول إلى Bits.', 'medium', 'OSI Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 3, 'ما أقصى طول موصى به لكابل الإيثرنت المزدوج المجدول (UTP Cat6) دون استخدام مقويات إشارة لضمان سلامة الإرسال؟', '50 متراً', '100 متر', '150 متراً', '500 متر', 'B', 'المعيار القياسي لكوابل الإيثرنت النحاسية UTP محدد بحد أقصى قدره 100 متر (90 متراً للكابل الصلب + 10 أمتار لكوابل التوصيل Patch Cords) وفق معايير TIA/EIA.', 'medium', 'Cabling & Physical');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 4, 'أي من الحقول التالية يوجد حصرياً في ترويسة (Header) بروتوكول TCP ولا يتواجد مطلقاً في ترويسة بروتوكول UDP؟', 'Source Port (منفذ المصدر)', 'Destination Port (منفذ الوجهة)', 'Sequence Number & Acknowledgment (أرقام التسلسل والتأكيد)', 'Checksum (المجموع الاختباري)', 'C', 'يتميز بروتوكول TCP بأنه موجه بالاتصال (Connection-Oriented) وموثوق، لذا يحتوي على Sequence Number و Acknowledgment Number لترتيب البيانات وتأكيد استلامها، بينما بروتوكول UDP خفيف وبسيط (Connectionless) ولا يحتوي على هذه الحقول.', 'medium', 'Transport Protocols');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 2, 'ما هو البروتوكول المسؤول عن اكتشاف ومعرفة عنوان MAC الفيزيائي المقابل لعنوان IPv4 معروف في نفس الشبكة المحلية؟', 'DNS (Domain Name System)', 'ARP (Address Resolution Protocol)', 'DHCP (Dynamic Host Configuration Protocol)', 'ICMP (Internet Control Message Protocol)', 'B', 'بروتوكول ARP يرسل رسالة بث عام (ARP Request Broadcast) ليسأل عن عنوان MAC الخاص بعنوان IP محدد، ويقوم الجهاز المعني بالرد برسالة أحادية (ARP Reply Unicast).', 'easy', 'Network Hardware');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 2, 'في شبكة إيثرنت حديثة تعمل بوضع الازدواج الكامل (Full-Duplex) بين جهاز حاسوب ومنفذ مبدل (Switch)، كم عدد مجالات التصادم الناتجة؟', 'مجال تصادم واحد مشترك بينهما', 'لا توجد أي مجالات تصادم على الإطلاق (Zero Collisions)', 'مجالان تصادم منفصلان', 'يتغير بحسب سرعة الكابل', 'B', 'في وضع الازدواج الكامل (Full-Duplex)، يتم استخدام أزواج أسلاك منفصلة للإرسال (Tx) والاستقبال (Rx)، مما يلغي حدوث أي تصادمات ميكانيكية بين الإشارات ويوفر قناة خالية تماماً من التصادم.', 'medium', 'Ethernet Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 2, 'كم عدد مجالات البث العام (Broadcast Domains) التي ينشئها راوتر يمتلك 4 منافذ GigabitEthernet نشطة متصل كل منها بمبدل مختلف؟', 'مجال بث واحد لجميع المنافذ', 'مجالان للبث فقط', '4 مجالات بث مستقلة تماماً', '8 مجالات بث', 'C', 'الراوتر (Router) يقوم بحجب رسائل البث العام (Broadcasts) بشكل افتراضي، وكل منفذ فيزيائي على الراوتر يمثل شبكة فرعية مستقلة ومجال بث منفصل تماماً (Broadcast Domain).', 'easy', 'Network Hardware');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 1, 'ما الذي يضاف في ذيل إطار البيانات (Trailer) في طبقة ربط البيانات (Data Link Layer) لاكتشاف الأخطاء التي قد تصيب الإشارة أثناء النقل؟', 'IP Header (ترويسة بروتوكول الإنترنت)', 'Frame Check Sequence (FCS / CRC)', 'Time to Live (TTL)', 'SYN Flag', 'B', 'تقوم طبقة ربط البيانات بإضافة حقل FCS في ذيل الإطار (Trailer) ويحتوي على ناتج خوارزمية فحص التكرار الدوري (CRC) للتأكد من وصول الإطار سليماً دون تشوه فيزيائي.', 'medium', 'OSI Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 3, 'كم عدد البتات (Bits) التي يتكون منها عنوان بروتوكول الإنترنت الإصدار السادس (IPv6)؟', '32 بت', '64 بت', '128 بت', '256 بت', 'C', 'يتكون عنوان IPv6 من 128 بت مقسمة إلى 8 مجموعات سداسية عشرية (Hexadecimal) تفصل بينها نقطتان، مما يمنح مساحة عنونة هائلة بلغت 2^128 عنواناً للقضاء على نفاد عناوين IPv4 المكونة من 32 بت فقط.', 'easy', 'IPv6 Fundamentals');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 3, 'ما هو نوع كابل الإيثرنت النحاسي المستخدم قديماً لتوصيل جهازين من نفس النوع مباشرة (مثل حاسوب بحاسوب، أو راوتر براوتر) قبل انتشار ميزة Auto-MDIX؟', 'Straight-Through Cable (كابل مستقيم)', 'Crossover Cable (كابل متعاكس)', 'Rollover Cable (كابل كونسول)', 'Coaxial Cable (كابل محوري)', 'B', 'الكابل المتعاكس (Crossover Cable) يبدل أزواج الإرسال (Tx) والاستقبال (Rx) عند الطرفين وفق معايير T568A و T568B، لتمكين جهازين يرسلان على نفس الأزواج من تبادل الإشارات.', 'medium', 'Cabling & Physical');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 2, 'كيف يقوم مبدل الإيثرنت (Switch) ببناء وتحديث جدول عناوين الـ MAC Address الخاص به؟', 'من خلال فحص عنوان MAC المصدر (Source MAC) في الإطارات الواردة', 'من خلال فحص عنوان MAC الوجهة (Destination MAC)', 'من خلال طلب قائمة العناوين من الراوتر الرئيسي', 'عبر إدخال يدوي إلزامي من المهندس لكل جهاز', 'A', 'عندما تصل إطارة إلى أي منفذ في المبدل، يقرأ المبدل عنوان MAC المصدر (Source MAC) ويربطه تلقائياً برقم المنفذ الذي دخلت منه الإطارة في جدول CAM Table مع مؤقت صلاحية (Aging Timer).', 'medium', 'Network Hardware');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 4, 'ما هو رقم المنفذ القياسي (Port Number) والبروتوكول المستخدم افتراضياً لمعظم استعلامات خوادم أسماء النطاقات (DNS Lookups)؟', 'Port 80 عبر TCP', 'Port 53 عبر UDP', 'Port 443 عبر TCP', 'Port 25 عبر UDP', 'B', 'تستخدم استعلامات DNS العادية المنفذ 53 عبر بروتوكول UDP لسرعته وقلة التكلفة الإضافية في الرسائل القصيرة، بينما يستخدم TCP Port 53 في نقل مناطق النطاقات (Zone Transfers) أو الرسائل الأكبر من 512 بايت.', 'easy', 'Transport Protocols');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 1, 'في نموذج TCP/IP المكون من 4 طبقات، أي طبقة تعادل وظيفياً الطبقات الثلاث العليا (Application, Presentation, Session) من نموذج OSI؟', 'Transport Layer (طبقة النقل)', 'Application Layer (طبقة التطبيقات)', 'Internet Layer (طبقة الإنترنت)', 'Network Access Layer (طبقة الوصول للشبكة)', 'B', 'في نموذج TCP/IP، تم دمج وظائف الطبقة السابعة والسادسة والخامسة (التطبيقات، التقديم، والجلسة) داخل طبقة واحدة تسمى طبقة التطبيقات (Application Layer).', 'easy', 'OSI Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (1, 4, 'ما هو الترتيب الدقيق للإشارات المتبادلة في المصافحة الثلاثية (Three-Way Handshake) لإنشاء جلسة اتصال TCP جديدة؟', 'ACK ثم SYN ثم SYN-ACK', 'SYN ثم SYN-ACK ثم ACK', 'SYN ثم ACK ثم FIN', 'DATA ثم ACK ثم FIN', 'B', 'تبدأ المصافحة بإرسال العميل إشارة SYN لطلب المزامنة، يرد الخادم بإشارة SYN-ACK للموافقة والمزامنة، وأخيراً يرد العميل بإشارة ACK لتأكيد بدء الاتصال الموثوق.', 'easy', 'Transport Protocols');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 5, 'ما هو عنوان الشبكة (Network ID) للمضيف الذي يحمل العنوان 192.168.10.130 بقناع /26؟', '192.168.10.0', '192.168.10.64', '192.168.10.128', '192.168.10.192', 'C', 'قناع /26 يعطي قفزة حجمها 64 (256 - 192 = 64). الشبكات الفرعية تبدأ عند: .0، .64، .128، .192. العنوان 130 يقع ضمن نطاق شبكة 192.168.10.128.', 'medium', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 6, 'كم عدد الأجهزة الصالحة للاستخدام (Usable Hosts) في شبكة فرعية تملك بادئة /28؟', '16 جهازاً', '14 جهازاً', '30 جهازاً', '12 جهازاً', 'B', 'عدد بتات المضيف المتبقية = 32 - 28 = 4 بت. إجمالي العناوين = 2^4 = 16. نطرح 2 للشبكة والبث فيتبقى 16 - 2 = 14 جهازاً صالحاً.', 'easy', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 7, 'ما هو عنوان البث العام (Broadcast Address) للشبكة الفرعية 172.16.4.0/22؟', '172.16.4.255', '172.16.7.255', '172.16.8.255', '172.16.15.255', 'B', 'في قناع /22 يتغير الثماني الثالث بحجم قفزة 2^(24-22) = 4. الشبكة تبدأ من 172.16.4.0 وتنتهي عند 172.16.7.255 كعنوان بث للشبكة.', 'hard', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 5, 'أي من العناوين التالية ينتمي إلى نطاق العناوين الخاصة المعتمدة في معيار RFC 1918؟', '172.35.10.1', '192.169.1.1', '10.200.5.1', '127.0.0.1', 'C', 'العناوين الخاصة لـ Class A هي من 10.0.0.0 إلى 10.255.255.255. العنوان 10.200.5.1 يقع داخل هذا النطاق، بينما 127.0.0.1 هو عنوان Loopback خاص بالجهاز.', 'easy', 'IPv4 Addressing');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 7, 'ما هو قناع البدل (Wildcard Mask) المكافئ لقناع الشبكة 255.255.255.240؟', '0.0.0.15', '0.0.0.31', '0.0.0.240', '255.255.255.0', 'A', 'لحساب قناع البدل نطرح قناع الشبكة من 255.255.255.255: ينتج 255-255=0، 255-255=0، 255-255=0، 255-240=15. الناتج: 0.0.0.15.', 'medium', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 8, 'وفقاً لمعيار RFC 3021، ما هو أصغر قناع شبكة يمكن استخدامه لتوصيل رابط نقطة لنقطة (Point-to-Point) بين راوترين دون هدر العناوين؟', '/30', '/31', '/32', '/29', 'B', 'معيار RFC 3021 يسمح باستخدام بادئة /31 على الروابط النقطية الموجهة؛ حيث يتم تخصيص العنوانين المتاحين لكلا الطرفين دون حجز عنوان للشبكة أو البث.', 'hard', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 5, 'ما هو عدد العناوين الصالحة للاستخدام من قبل الأجهزة (Usable Hosts) في شبكة فرعية تملك قناع 255.255.255.224 (/27)؟', '32 جهازاً', '30 جهازاً', '62 جهازاً', '14 جهازاً', 'B', 'قناع /27 يترك 32 - 27 = 5 بتات للمضيفين. إجمالي العناوين هو 2^5 = 32 عنواناً. نطرح عنوان الشبكة وعنوان البث العام (32 - 2) فيتبقى 30 عنواناً متاحاً للأجهزة.', 'easy', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 5, 'إذا كان جهاز حاسوب يحمل العنوان 10.10.15.65 بقناع 255.255.255.192 (/26)، فما هو عنوان الشبكة الفرعية (Network ID) التي ينتمي إليها؟', '10.10.15.0', '10.10.15.64', '10.10.15.32', '10.10.15.128', 'B', 'قناع /26 قيمته 192 في الثماني الرابع، مما يعطي حجم كتلة (Block Size) قدره 256 - 192 = 64. الشبكات تبدأ عند .0 ثم .64 ثم .128. العنوان .65 يقع مباشرة في شبكة 10.10.15.64/26.', 'medium', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 6, 'ما هو عنوان البث العام (Broadcast Address) للشبكة الفرعية 192.168.1.16/29؟', '192.168.1.23', '192.168.1.24', '192.168.1.31', '192.168.1.255', 'A', 'قناع /29 يعادل 255.255.255.248 بحجم قفزة 2^(32-29) = 8. تبدأ الشبكة عند 192.168.1.16 والشبكة التالية تبدأ عند .24، وبالتالي يكون العنوان الأخير قبل الشبكة التالية هو عنوان البث: 192.168.1.23.', 'medium', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 7, 'عندما يفشل جهاز حاسوب في الوصول إلى خادم DHCP، ما هو نطاق العناوين الذي يولد منه عنوان APIPA تلقائياً (Link-Local)؟', '10.0.0.0/8', '169.254.0.0/16', '192.168.0.0/16', '127.0.0.0/8', 'B', 'خاصية APIPA (Automatic Private IP Addressing) المحددة بمعيار RFC 3927 تخصص تلقائياً عنواناً من نطاق 169.254.0.1 إلى 169.254.255.254 عندما يتعذر على الجهاز استلام IP من خادم DHCP.', 'easy', 'IPv4 Addressing');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 7, 'أي من فئات العناوين التالية (Address Classes) مخصصة للبث متعدد الوجهات (Multicast) في بروتوكول IPv4؟', 'Class A (1.0.0.0 to 126.255.255.255)', 'Class B (128.0.0.0 to 191.255.255.255)', 'Class C (192.0.0.0 to 223.255.255.255)', 'Class D (224.0.0.0 to 239.255.255.255)', 'D', 'الفئة Class D تمتد من 224.0.0.0 إلى 239.255.255.255 ومخصصة لخدمات البث متعدد الوجهات (Multicast)، مثل بروتوكولات التوجيه OSPF (224.0.0.5) وبث الوسائط المتعددة.', 'easy', 'IPv4 Addressing');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 8, 'ما هو المعيار الدولي القياسي المستخدم لإضافة وسم (VLAN Tagging) للإطارات عبر منافذ الـ Trunk في مبدلات الشبكة؟', 'Cisco ISL (Inter-Switch Link)', 'IEEE 802.1Q (Dot1Q)', 'IEEE 802.3u', 'IEEE 802.11ax', 'B', 'معيار IEEE 802.1Q هو المعيار المفتوح المعتمد عالمياً لإضافة وسم بحجم 4 بايت يحتوي على معرف الـ VLAN (VLAN ID من 1 إلى 4094) لتمرير حركة بيانات عدة شبكات افتراضية عبر منفذ Trunk واحد.', 'medium', 'VLANs & Trunking');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 8, 'ما هو مفهوم الـ Native VLAN في روابط الـ Trunk وفق معيار 802.1Q في مبدلات سيسكو؟', 'الشبكة الافتراضية المخصصة لحركة البيانات بدون وسم (Untagged Frames)', 'الشبكة الوحيدة المسموح لها بنقل البيانات عبر المبدل', 'شبكة مخصصة فقط لأوامر سيسكو المشفرة', 'شبكة افتراضية تلغي الحاجة للراوتر', 'A', 'الـ Native VLAN (وافتراضياً هي VLAN 1 في سيسكو) هي الشبكة التي تنقل الإطارات بدون إضافة وسم 802.1Q؛ وتعتبر مطابقة Native VLAN على طرفي رابط الـ Trunk مطلباً أمنياً أساسياً لمنع VLAN Hopping.', 'medium', 'VLANs & Trunking');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 6, 'ما هو أفضل عنوان ملخص (Route Summarization / CIDR) يجمع الشبكات الأربع التالية: 192.168.0.0/24 و 192.168.1.0/24 و 192.168.2.0/24 و 192.168.3.0/24؟', '192.168.0.0/21', '192.168.0.0/22', '192.168.0.0/23', '192.168.0.0/16', 'B', 'القيم الثنائية للثماني الثالث: 0 (00000000), 1 (00000001), 2 (00000010), 3 (00000011). تتطابق البتات الست الأولى، فنستعير 6 بتات من الثماني الثالث: 16 + 6 = 22 بت. العنوان الملخص الدقيق هو 192.168.0.0/22.', 'hard', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 5, 'شبكة مؤسسة تحتاج لتخصيص شبكة فرعية من 172.16.0.0/16 تستوعب 500 جهاز حاسوب على الأقل في مبنى الإدارة. ما هو أصغر قناع شبكة يحقق هذا المتطلب؟', '/24 (255.255.255.0)', '/23 (255.255.254.0)', '/22 (255.255.252.0)', '/25 (255.255.255.128)', 'B', 'لحساب عدد البتات المطلوبة: 2^n - 2 >= 500. إذا اخترنا n = 9 بت: 2^9 - 2 = 512 - 2 = 510 أجهزة (قناع /23). بينما قناع /24 يوفر 254 جهازاً فقط وهو غير كافٍ. لذا /23 هو الحل الأمثل دون هدر.', 'hard', 'VLSM Design');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 7, 'ما هي الوظيفة الأساسية لعنوان البوابة الافتراضية (Default Gateway) المكون في إعدادات الشبكة لجهاز الحاسوب؟', 'تزويد الجهاز بعنوان IP تلقائي عبر الشبكة', 'توجيه الحزم المتجهة إلى شبكات فرعية ووجهات تقع خارج الشبكة المحلية', 'فحص الكابلات بحثاً عن انقطاع فيزيائي', 'تسريع سرعة معالج الحاسوب', 'B', 'عندما يقارن الحاسوب عنوان وجهة الحزمة بعنوانه وقناعه ويكتشف أن الوجهة تقع في شبكة أخرى، يرسل الحزمة إلى عنوان البوابة الافتراضية (وهو منفذ الراوتر المحلي) ليتولى توجيهها.', 'easy', 'IPv4 Addressing');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (2, 6, 'ما هو قناع البدل (Wildcard Mask) المستخدم مع قناع الشبكة 255.255.240.0 في إعدادات قوائم سيسكو؟', '0.0.15.255', '0.0.31.255', '0.0.0.240', '255.255.15.0', 'A', 'يتم طرح قناع الشبكة من 255.255.255.255: (255-255=0), (255-255=0), (255-240=15), (255-0=255). الناتج هو 0.0.15.255.', 'medium', 'Subnetting & CIDR');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 9, 'إذا تعلم الراوتر مساراً لنفس الشبكة عبر التوجيه الثابت وعبر OSPF وعبر RIP، فأي مسار سيتم وضعه في جدول التوجيه؟', 'مسار OSPF لأن خوارزميته أسرع', 'المسار الثابت (Static Route) لأن مسافته الإدارية أقل', 'مسار RIP لأن مقياسه أبسط', 'يتم توزيع الأحمال بالتساوي بينها', 'B', 'الراوتر يختار المسار ذو المسافة الإدارية (AD) الأقل أولاً؛ والمسار الثابت مسافته الإدارية 1 مقارنة بـ 110 لـ OSPF و 120 لـ RIP.', 'medium', 'Routing Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 10, 'ما الخوارزمية الرياضية التي يعتمد عليها بروتوكول OSPF لحساب أقصر مسار وبناء شجرة التوجيه الخالية من الحلقات؟', 'Bellman-Ford', 'Dijkstra (Shortest Path First)', 'DUAL Algorithm', 'Spanning Tree Algorithm', 'B', 'يعتمد بروتوكول OSPF على خوارزمية ديكسترا (Dijkstra SPF) لتحديد المسار الأقل تكلفة من الراوتر المحلي إلى جميع الشبكات الواردة في قاعدة LSDB.', 'easy', 'OSPF Dynamics');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 12, 'ما هو الهدف الهندسي الأساسي من تشغيل بروتوكول شجرة الامتداد (Spanning Tree Protocol - STP) في شبكات المبدلات؟', 'زيادة سرعة المنافذ للضعف', 'منع حلقات التبديل (Switching Loops) وعواصف البث', 'تشفير الإطارات المنقولة بين المنافذ', 'توزيع عناوين IP تلقائياً', 'B', 'يقوم بروتوكول STP بمنع حلقات التبديل الخطيرة في الطبقة الثانية عبر حجب المنافذ الفائضة منطقياً وإبقائها كمسارات احتياطية في حال تعطل المسار الرئيسي.', 'easy', 'Switching & STP');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 10, 'ما هي منطقة العمود الفقري الإلزامية في بروتوكول OSPF متعدد المناطق والتي يجب أن تتصل بها جميع المناطق الأخرى؟', 'Area 1', 'Area 0 (Backbone Area)', 'Area 100', 'Area 255', 'B', 'منطقة Area 0 هي العمود الفقري لبروتوكول OSPF (Backbone)، وتلزم معايير سيسكو وIETF ربط جميع المناطق الأخرى بها مباشرة لمنع حلقات التوجيه بين المناطق.', 'medium', 'OSPF Dynamics');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 11, 'أي نوع من بروتوكولات التوجيه هو بروتوكول BGP المستخدم عالمياً لتبادل مسارات الإنترنت بين الأنظمة المستقلة (AS)؟', 'Interior Gateway Protocol (Link-State)', 'Path-Vector Protocol', 'Distance-Vector Protocol', 'Pure Static Engine', 'B', 'بروتوكول BGP يصنف كـ Path-Vector Protocol؛ حيث يتتبع قائمة الأنظمة المستقلة (AS-Path) التي تعبرها الحزمة لضمان منع حلقات التوجيه بين الشبكات العالمية.', 'hard', 'BGP & Internet Routing');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 12, 'كيف يختار بروتوكول STP المبدل الجذري (Root Bridge) في الشبكة المحلية؟', 'المبدل صاحب أعلى عنوان MAC', 'المبدل صاحب أقل قيمة Bridge ID (Priority + MAC)', 'أول مبدل يتم تشغيله فيزيائياً', 'المبدل الذي يملك منافذ بسرعة 10 Gbps', 'B', 'يتم انتخاب المبدل الجذري صاحب أقل قيمة Bridge ID، والتي تتكون من الأولوية (Priority) ثم عنوان MAC الأقل في حال تساوي الأولوية.', 'medium', 'Switching & STP');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 10, 'كيف يتم حساب مقياس التكلفة (Cost Metric) لمنفذ الراوتر في بروتوكول OSPF وفق المعادلة الافتراضية في سيسكو؟', 'عدد القفزات (Hop Count) مقسوماً على 15', 'Reference Bandwidth (100 Mbps) مقسوماً على Interface Bandwidth', 'تأخير القناة (Delay) مضروباً في الموثوقية', 'قيمة ثابتة تساوي 10 لجميع المنافذ', 'B', 'معادلة تكلفة OSPF الافتراضية هي: Cost = Reference Bandwidth (10^8 bps = 100 Mbps) / Interface Bandwidth bps. منفذ FastEthernet تكلفته 1، بينما 10 Mbps تكلفته 10.', 'medium', 'OSPF Dynamics');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 10, 'في شبكة OSPF متعددة الوصول (Broadcast Multiaccess)، كيف يتم انتخاب الراوتر المعين الرئيسي (Designated Router - DR)؟', 'الراوتر صاحب أقل عنوان IP للمنفذ', 'الراوتر صاحب أعلى OSPF Priority، ثم صاحب أعلى Router ID في حال التعادل', 'الراوتر المتصل مباشرة بالإنترنت فقط', 'يتم اختياره عشوائياً بواسطة خوارزمية ديكسترا', 'B', 'يتم انتخاب DR و BDR بناءً على أعلى قيمة OSPF Priority (من 1 إلى 255، والقيمة 0 تعني عدم المشاركة)، وفي حال التعادل يفوز الراوتر صاحب أعلى Router ID.', 'medium', 'OSPF Dynamics');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 9, 'ما هو المسار الثابت العائم (Floating Static Route) وكيف يتم تكوينه في أجهزة التوجيه؟', 'مسار ديناميكي يتعلم المسارات من السحابة مباشرة', 'مسار ثابت تم تعيين مسافة إدارية له (AD) أعلى من البروتوكول الأساسي ليعمل كمسار احتياطي فقط عند تعطل المسار الرئيسي', 'مسار ثابت بدون عنوان بوابة افتراضية', 'مسار خاص ببروتوكول RIP فقط', 'B', 'المسار الثابت العائم يُعطى مسافة إدارية أكبر (مثلاً 120 أو 130) من OSPF (110)؛ فيظل مختفياً من جدول التوجيه طالما OSPF نشط، ويظهر تلقائياً كمسار احتياطي فوري إذا تعطل مسار OSPF.', 'hard', 'Routing Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 12, 'ما هو الترتيب الصحيح للحالات الأربع التي يمر بها منفذ المبدل في بروتوكول STP التقليدي (802.1D) قبل البدء في نقل حزم المستخدم؟', 'Listening -> Blocking -> Learning -> Forwarding', 'Blocking -> Listening -> Learning -> Forwarding', 'Forwarding -> Learning -> Listening -> Disabled', 'Learning -> Listening -> Forwarding -> Blocking', 'B', 'يمر المنفذ في STP التقليدي بحالة Blocking (حجب)، ثم Listening (استماع لرسائل BPDU لمدة 15 ثانية)، ثم Learning (بناء جدول MAC لمدة 15 ثانية)، ثم ينتقل أخيراً لحالة Forwarding لتمرير البيانات.', 'medium', 'Switching & STP');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 12, 'ما هو المعيار المطور لبروتوكول الشجرة الممتدة الذي يختصر وقت التقارب (Convergence) من 50 ثانية إلى أقل من ثانيتين؟', 'IEEE 802.1D (STP)', 'IEEE 802.1w (Rapid Spanning Tree Protocol - RSTP)', 'IEEE 802.1s (MSTP)', 'IEEE 802.3ad', 'B', 'معيار RSTP (802.1w) يقدم آليات تفاوض استباقية (Proposal/Agreement Handshake) وحالات منافذ جديدة تختصر التقارب إلى أجزاء من الثانية بدلاً من مؤقتات STP الطويلة.', 'easy', 'Switching & STP');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 9, 'ما هي تقنية (Router-on-a-Stick) المستخدمة في توجيه حركة البيانات بين شبكات الـ VLAN المختلفة (Inter-VLAN Routing)؟', 'توصيل كابل منفصل لكل جهاز حاسوب مباشرة بالراوتر', 'استخدام منفذ فيزيائي واحد على الراوتر مقسم إلى منافذ فرعية منطقية (Sub-interfaces) مع كبسلة 802.1Q', 'إلغاء تشغيل الراوتر واستبداله بموزع قديم Hub', 'استخدام اتصال لاسلكي حصري', 'B', 'تعتمد طريقة Router-on-a-Stick على إنشاء Sub-interfaces (مثل g0/0.10 و g0/0.20) وتفعيل أمر encapsulation dot1Q لتعمل كل منها كبوابة افتراضية لشبكة VLAN مستقلة عبر كابل Trunk واحد.', 'medium', 'VLAN Routing');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 12, 'ما هو البروتوكول المعياري المفتوح المعتمد من IEEE لتجميع عدة روابط فيزيائية في رابط منطقي فائق السرعة (EtherChannel)؟', 'PAgP (Port Aggregation Protocol)', 'LACP (Link Aggregation Control Protocol - IEEE 802.3ad)', 'VTP (VLAN Trunking Protocol)', 'CDP (Cisco Discovery Protocol)', 'B', 'بروتوكول LACP هو المعيار الصناعي المفتوح (IEEE 802.3ad / 802.1AX) لتجميع ما يصل إلى 8 روابط فيزيائية نشطة في رابط EtherChannel واحد، بينما PAgP هو بروتوكول خاص بسيسكو.', 'easy', 'EtherChannel Dynamics');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 10, 'ما وظيفة الأمر `passive-interface` عند تطبيقه على منفذ في إعدادات بروتوكول OSPF على راوتر سيسكو؟', 'تعطيل المنفذ فيزيائياً وإيقاف مرور الكهرباء فيه', 'إيقاف إرسال رسائل OSPF Hello عبر المنفذ مع استمرار الإعلان عن شبكة المنفذ لباقي الراوترات', 'تحويل المنفذ للعمل كـ Default Gateway فقط', 'تشفير جميع الحزم الخارجة من المنفذ', 'B', 'استخدام passive-interface على المنافذ المتصلة بأجهزة المستخدمين النهائية يمنع إرسال رسائل Hello غير الضرورية ويوفر الموارد ويعزز الأمان لمنع اختراق جيران OSPF غير المصرح بهم.', 'medium', 'OSPF Dynamics');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 12, 'ما هي الفائدة الهندسية المباشرة من تفعيل ميزة `spanning-tree portfast` على منافذ مبدل سيسكو المتصلة بأجهزة الحاسوب؟', 'مضاعفة سرعة النقل من 1 Gbps إلى 10 Gbps', 'نقل المنفذ فوراً إلى حالة Forwarding متجاوزاً فترات الاستماع والتعلم (30 ثانية)', 'حجب هجمات حجب الخدمة تلقائياً', 'توزيع عناوين IP تلقائياً بدون DHCP', 'B', 'تسمح ميزة PortFast للأجهزة الطرفية (Access Ports) بالحصول على اتصال فوري بالشبكة دون انتظار الـ 30 ثانية الخاصة بحالات Listening و Learning، مما يمنع مشاكل مهلة استلام عنوان DHCP.', 'easy', 'Switching & STP');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 11, 'ما هو المعرّف الفريد عالمياً المستخدم لتمييز الأنظمة المستقلة وتوجيه البيانات بينها عبر بروتوكول BGP في شبكة الإنترنت؟', 'MAC Address', 'Autonomous System Number (ASN)', 'VLAN ID', 'Default Gateway ID', 'B', 'رقم النظام المستقل (ASN) هو رقم فريد عالمياً يتم تخصيصه من قبل هيئة IANA/RIRs للشركات ومزودي خدمة الإنترنت (ISPs) لتمكين بروتوكول BGP من توجيه حركة البيانات العالمية بدقة.', 'medium', 'BGP & Internet Routing');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (3, 9, 'إذا تعلم الراوتر مسارين لنفس الشبكة الفرعية تماماً: أحدهما عبر OSPF والآخر عبر EIGRP الداخلي، فأي مسار سيختاره؟', 'مسار OSPF لأن خوارزميته مفتوحة المصدر', 'مسار EIGRP لأن مسافته الإدارية (AD = 90) أقل من OSPF (AD = 110)', 'يتم تقسيم الحزم مناصفة بينهما', 'يرفض الراوتر كلا المسارين ويعلن عن خطأ', 'B', 'الراوتر يقارن المسافة الإدارية (Administrative Distance) أولاً قبل أي مقياس آخر؛ وبما أن AD لبروتوكول EIGRP الداخلي هي 90 مقارنة بـ 110 لبروتوكول OSPF، فإن مسار EIGRP هو الفائز ويوضع في جدول التوجيه.', 'medium', 'Routing Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 13, 'أين يوصى هندسياً بوضع قوائم التحكم بالوصول الموسعة (Extended ACLs) في الشبكة؟', 'بالقرب من الوجهة (Destination) قدر الإمكان', 'بالقرب من المصدر (Source) قدر الإمكان', 'على جميع منافذ الـ Switch الافتراضية', 'في أي نقطة دون أي فارق هندسي', 'B', 'توضع Extended ACL بالقرب من المصدر لحجب الحركات غير المرغوبة فور نشوئها، مما يوفر سعة القنوات وموارد المعالجة للراوترات الوسيطة.', 'medium', 'Access Control Lists');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 14, 'ما الميزة الجوهرية للجدران النارية ذات فحص الحالة (Stateful Inspection) مقارنة بالمرشحات البسيطة (Stateless)؟', 'تمنع الفيروسات من كوابل الشبكة', 'تتبع حالة الجلسات النشطة وتسمح تلقائياً بحزم الاستجابة الشرعية للمستخدمين', 'تلغي الحاجة لعناوين الـ IP في الشبكة', 'تعمل في الطبقة الفيزيائية فقط', 'B', 'تحتفظ الجدران النارية ذات فحص الحالة بجدول حالات الجلسات (State Table)، مما يمكنها من السماح بالردود الشرعية الناتجة عن اتصالات أنشأها المستخدمون من الداخل تلقائياً.', 'medium', 'Firewalls & Defense');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 15, 'أي من بروتوكولات حزمة IPsec التالية يوفر سرية البيانات عبر التشفير الكامل (Confidentiality) بالإضافة إلى التحقق من النزاهة؟', 'Authentication Header (AH)', 'Encapsulating Security Payload (ESP)', 'Internet Key Exchange (IKE) Phase 1 فقط', 'DHCP Snooping', 'B', 'بروتوكول ESP (IP Protocol 50) هو البروتوكول المسؤول عن توفير التشفير لسرية البيانات إلى جانب سلامتها ومصادقتها، بينما AH يوفر التحقق من النزاهة فقط دون تشفير.', 'medium', 'VPN & IPsec');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 13, 'ما الذي يحدث لحزمة بيانات لا تطابق أي قاعدة من القواعد المكتوبة صراحة في قائمة تحكم بالوصول (ACL) على راوتر سيسكو؟', 'يتم تمريرها تلقائياً إلى الوجهة', 'يتم إسقاطها وحجبها بسبب قاعدة الحجب الضمني (Implicit Deny)', 'يتم إرسالها إلى منفذ الإدارة فقط', 'يقوم الراوتر بإعادة تشغيل نفسه', 'B', 'تحتوي كل قائمة ACL في نهايتها على أمر غير مرئي هو Implicit Deny Any؛ لذا يتم إسقاط أي حزمة لم تطابق قاعدة سماح صريحة تسبقها.', 'easy', 'Access Control Lists');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 16, 'ما هو المبدأ الأساسي الذي تنطلق منه معمارية الأمان الحديثة Zero Trust في المؤسسات؟', 'الوثوق التام بجميع الموظفين داخل الشبكة الداخلية', 'عدم الثقة التلقائية بأي مستخدم أو جهاز سواء داخل الشبكة أو خارجها والتحقق المستمر', 'الاعتماد على كلمات المرور المكونة من 4 أرقام', 'إلغاء تشفير البيانات داخل الشبكة المحلية', 'B', 'معمارية Zero Trust تتبنى مبدأ \"Never Trust, Always Verify\"، حيث تفترض وجود تهديدات محتملة حتى داخل الشبكة المحلية وتلزم التحقق المستمر والصلاحيات الصارمة.', 'easy', 'Zero Trust Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 15, 'ما الغرض من خوارزمية Diffie-Hellman (DH) أثناء مرحلة التفاوض في نفق IPsec VPN؟', 'تشفير ملفات المستخدم النهائية', 'تبادل المفاتيح السرية المشتركة عبر قناة اتصال غير آمنة', 'حساب عنوان الـ Broadcast للشبكة', 'تحديد أرقام المنافذ لبروتوكول UDP', 'B', 'خوارزمية ديفي هيلمان (Diffie-Hellman) تتيح لطرفين إنشاء مفتاح تشفير متماثل مشترك بينهما عبر شبكة غير آمنة دون إرسال المفتاح نفسه عبر الشبكة.', 'hard', 'VPN & IPsec');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 13, 'ما هو النطاق الرقمي القياسي المخصص لقوائم التحكم بالوصول الموسعة (Extended Numbered ACLs) في راوترات سيسكو؟', 'من 1 إلى 99 ومن 1300 إلى 1999', 'من 100 إلى 199 ومن 2000 إلى 2699', 'من 500 إلى 599 فقط', 'من 1000 إلى 1099', 'B', 'في راوترات سيسكو، الأرقام 1-99 و 1300-1999 مخصصة لـ Standard ACL، بينما الأرقام 100-199 و 2000-2699 مخصصة لـ Extended ACL التي تفحص المصدر والوجهة والبروتوكول وأرقام المنافذ.', 'easy', 'Access Control Lists');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 14, 'ما هي تقنية ترجمة العناوين التي تسمح لآلاف الأجهزة في الشبكة الداخلية بمشاركة عنوان IPv4 عمومي واحد للوصول إلى الإنترنت؟', 'Static NAT (1-to-1)', 'Port Address Translation (PAT / NAT Overload)', 'Dynamic NAT Pool', 'Proxy ARP', 'B', 'تقنية PAT (تسمى أيضاً NAT Overload) تعين لكل اتصال داخلي رقم منفذ مصدر فريد (Source Port) على نفس عنوان الـ IP العمومي، مما يتيح لأكثر من 65,000 جلسة متزامنة مشاركة عنوان IP عام واحد.', 'medium', 'NAT & Translation');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 16, 'في ميزة Port Security على مبدلات سيسكو، أي وضع انتهاك (Violation Mode) يقوم بإيقاف المنفذ تماماً ونقله لحالة err-disable؟', 'Protect Mode', 'Restrict Mode', 'Shutdown Mode', 'Bypass Mode', 'C', 'وضع Shutdown هو الوضع الافتراضي والأكثر صرامة؛ فعند اتصال جهاز بعنوان MAC غير مصرح به، يقوم المبدل بإسقاط الحزم فوراً وإرسال تنبيه SNMP ونقل المنفذ لحالة err-disable حتى يعاد تشغيله يدوياً.', 'medium', 'Switch Security');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 16, 'ما هو الهجوم الأمني الخطير في الطبقة الثانية الذي صُممت ميزة DHCP Snooping لمنعه وحماية المستخدمين منه؟', 'هجوم خادم DHCP المخادع (Rogue DHCP Server) واستنزاف العناوين (DHCP Starvation)', 'هجمات حجب الخدمة على كابلات الألياف الضوئية', 'تجاوز سعة بطاقة الذاكرة في الراوتر', 'سرقة كلمة سر شاشة القفل للحاسوب', 'A', 'تقسم ميزة DHCP Snooping منافذ المبدل إلى Trusted (متصلة بخادم DHCP الشرعي) و Untrusted (منافذ المستخدمين) وتسقط فوراً أي رسائل DHCP Offer/ACK قادمة من منافذ المستخدمين غير الموثوقة لمنع هجمات Man-in-the-Middle.', 'medium', 'Switch Security');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 15, 'ما هو الهدف الأساسي من المرحلة الأولى (Phase 1 / IKE SA) في مفاوضات إنشاء نفق IPsec VPN؟', 'نقل ملفات المستخدمين غير المشفرة مباشرة', 'إنشاء نفق اتصال آمن ومشفر للمصادقة وحماية مفاوضات معايير النفق في المرحلة الثانية', 'حساب عناوين الـ MAC Address للأجهزة البعيدة', 'تثبيت برامج مكافحة الفيروسات على الراوترات', 'B', 'في Phase 1 (IKEv1 / IKEv2)، يتفاوض الطرفان على خوارزميات التشفير (AES)، والتجزئة (SHA)، والمصادقة (PSK/Certificates)، ومجموعة Diffie-Hellman لإنشاء نفق ISAKMP SA الآمن الذي تُدار من خلاله مفاوضات Phase 2.', 'hard', 'VPN & IPsec');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 14, 'كيف تساهم جدران الحماية المتقدمة (Stateful Firewalls) في صد هجمات حجب الخدمة من نوع TCP SYN Flood؟', 'بإلغاء بروتوكول TCP من الشبكة بالكامل', 'باستخدام آلية SYN Cookies ومراقبة جدول الجلسات النشطة لتفقد الاتصالات غير المكتملة', 'بزيادة سعة القرص الصلب في السيرفر', 'بفصل كابل الكهرباء عن الخادم', 'B', 'تستخدم جدران الحماية تقنية SYN Cookies أو فحص الاتصالات نصف المفتوحة (Half-Open Connections) حيث لا تحجز موارد الذاكرة للاتصال إلا بعد إتمام المصافحة الثلاثية بوصول إشارة الـ ACK الشرعية من العميل.', 'hard', 'Firewalls & Defense');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 16, 'ما هي الركائز الثلاث الأساسية التي يشير إليها مثلث أمن المعلومات الشهير (CIA Triad)؟', 'Cables, Internet, Access', 'Confidentiality (السرية), Integrity (النزاهة), Availability (التوافرية)', 'Control, Inspection, Authentication', 'Cryptography, IP, Antivirus', 'B', 'مثلث CIA هو النموذج المعياري لأمن المعلومات: السرية (Confidentiality - حصر الوصول للمصرح لهم)، النزاهة (Integrity - ضمان عدم تزوير البيانات)، والتوافرية (Availability - ضمان إتاحة الخدمات عند طلبها).', 'easy', 'Security Fundamentals');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 16, 'على ماذا تعتمد ميزة الفحص الديناميكي لحزم ARP (Dynamic ARP Inspection - DAI) في التحقق من صحة حزم ARP ومنع هجمات التسميم ARP Poisoning؟', 'قاعدة بيانات عناوين الـ DNS العالمية', 'جدول الربط الناتج عن ميزة DHCP Snooping (DHCP Snooping Binding Database)', 'سرعة المعالج في الراوتر الرئيسي', 'قائمة كلمات السر في نظام التشغيل', 'B', 'تقوم ميزة DAI بمقارنة عنوان IP وعنوان MAC وحقل المنفذ في كل حزمة ARP بالبيانات المخزنة مسبقاً في جدول DHCP Snooping Binding Table، وتسقط الحزمة فوراً إذا كانت بياناتها غير مطابقة لمنع هجمات التسميم.', 'hard', 'Switch Security');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 15, 'ما هو الفارق الجوهري بين التشفير المتماثل (Symmetric Encryption) والتشفير غير المتماثل (Asymmetric Encryption)؟', 'المتماثل يستخدم نفس المفتاح للتشفير وفك التشفير، بينما غير المتماثل يستخدم زوج مفاتيح (عام للتشفير وخاص لفك التشفير)', 'غير المتماثل أسرع بآلاف المرات من المتماثل', 'المتماثل لا يحتاج لأي مفاتيح رياضية', 'غير المتماثل يستخدم فقط في شبكات البلوتوث', 'A', 'التشفير المتماثل (مثل AES) سريع جداً ويستخدم نفس المفتاح السري، بينما غير المتماثل (مثل RSA و ECC) يستخدم مفتاحاً عاماً (Public Key) معلناً ومفتاحاً خاصاً (Private Key) سرياً لحل معضلة توزيع المفاتيح.', 'medium', 'Cryptography & Security');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 16, 'وفق منهجية الأمان الحديثة (Zero Trust Architecture)، ما هو المبدأ الحاكم عند محاولة جهاز موظف الاتصال بخادم قاعدة بيانات داخل المقر الرئيسي للشركة؟', 'منحه الثقة الكاملة بدون فحص لأنه متصل بالشبكة السلكية الداخلية للمكتب', 'إلزام الجهاز والمستخدم بالمصادقة الصارمة والتحقق من صحة الجهاز وتطبيق مبدأ الصلاحيات الأدنى (Least Privilege) باستمرار', 'إيقاف تشغيل الخادم فوراً للاشتباه بالأمان', 'السماح له بالدخول إذا كان اسم المستخدم يبدأ بحرف إنجليزي', 'B', 'منهجية Zero Trust تنص على: Never Trust, Always Verify. أي أنه لا توجد منطقة موثوقة حتى داخل محيط الشبكة الداخلية، ويلزم التحقق المستمر من الهوية وسلوك الجهاز وموقع الاتصال.', 'easy', 'Zero Trust Architecture');
INSERT INTO `questions` (`level_id`, `topic_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `difficulty`, `domain_name`) VALUES (4, 13, 'في راوتر سيسكو، ما هو الفرق الأساسي في التطبيق بين الأمر `ip access-group 101 in` والأمر `ip access-group 101 out` على منفذ الواجهة؟', 'الأمر `in` يفحص الحزم الواردة إلى الراوتر قبل اتخاذ قرار التوجيه، بينما `out` يفحص الحزم بعد توجيهها وقبل خروجها من المنفذ', 'الأمر `in` يخص بروتوكول IPv6 فقط بينما `out` يخص IPv4', 'الأمران متطابقان تماماً ولا يوجد أي فارق في الأداء', 'الأمر `out` يقوم بمسح الـ ACL نهائياً من الذاكرة', 'A', 'تطبيق ACL كـ `in` يفحص الحزمة فور دخولها من المنفذ ويسقطها قبل استهلاك موارد المعالج في عملية التوجيه، بينما `out` يفحص الحزمة بعد أن حدد الراوتر مسارها وأصبحت جاهزة للإرسال عبر ذلك المنفذ.', 'medium', 'Access Control Lists');
